-- SELECT only. Run after apply. 예/아니오 항목은 모두 예, 그 밖의 값은 precheck의 같은 이름 항목과 같은 값이어야 한다
-- (표 12개의 줄 수·기존 정책·표 권한·기존 트리거 해시 변화 없음). 값은 집계·해시만, id는 내보내지 않는다.
select 'history row present' as item,case when (select count(*) from supabase_migrations.schema_migrations where version='20261029090000' and name='operator_features')=1 then '예' else '아니오' end as value
union all select 'allow table: RLS on, no policies, no API role privileges',case when exists(select 1 from pg_class where oid=to_regclass('public.app_operator_features') and relrowsecurity) and not exists(select 1 from pg_policy where polrelid=to_regclass('public.app_operator_features')) and not has_any_column_privilege('anon','public.app_operator_features','select,insert,update') and not has_any_column_privilege('authenticated','public.app_operator_features','select,insert,update') and not has_any_column_privilege('service_role','public.app_operator_features','select,insert,update') and not has_table_privilege('authenticated','public.app_operator_features','delete') and not has_table_privilege('service_role','public.app_operator_features','delete') and coalesce((select relacl::text from pg_class where oid=to_regclass('public.app_operator_features')),'')!~'(^|[{,])(anon|authenticated|service_role)?=' then '예' else '아니오' end
union all select 'allow rows: calls and telegram for the one data workspace only',case when (select count(*) from public.app_operator_features)=2 and (select count(distinct workspace_id) from public.app_operator_features)=1 and (select count(*) from public.app_operator_features where feature in('calls','telegram'))=2 and (select count(*) from public.app_operator_features f where f.workspace_id in(select workspace_id from public.app_feed_items union select workspace_id from public.app_feed_days union select workspace_id from public.app_call_personal))=2 then '예' else '아니오' end
union all select 'twelve restrictive read policies (authenticated, feature check)',case when (select count(*) from pg_policy p where p.polrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_days'),to_regclass('public.app_call_personal'),to_regclass('public.app_call_edits'),to_regclass('public.app_call_edit_history'),to_regclass('public.app_tg_senders'),to_regclass('public.app_tg_day_senders'),to_regclass('public.app_feed_folders'),to_regclass('public.app_feed_rooms'),to_regclass('public.app_feed_room_days'),to_regclass('public.app_feed_summary_edits'),to_regclass('public.app_feed_summary_edit_history')) and p.polname='op_feature_read' and not p.polpermissive and p.polcmd='r' and p.polroles=array['authenticated'::regrole]::oid[] and pg_get_expr(p.polqual,p.polrelid) like '%app_workspace_has_feature%' and p.polwithcheck is null)=12 then '예' else '아니오' end
union all select 'twelve enabled guard triggers (before insert or update, row)',case when (select count(*) from pg_trigger t where t.tgrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_days'),to_regclass('public.app_call_personal'),to_regclass('public.app_call_edits'),to_regclass('public.app_call_edit_history'),to_regclass('public.app_tg_senders'),to_regclass('public.app_tg_day_senders'),to_regclass('public.app_feed_folders'),to_regclass('public.app_feed_rooms'),to_regclass('public.app_feed_room_days'),to_regclass('public.app_feed_summary_edits'),to_regclass('public.app_feed_summary_edit_history')) and t.tgname='trg_op_feature_guard' and t.tgenabled='O' and t.tgfoid=to_regprocedure('private.app_operator_feature_guard()') and t.tgtype=23)=12 then '예' else '아니오' end
union all select 'four definer functions: empty search_path, no anon or PUBLIC execute',case when (select count(*) from pg_proc p where p.oid in(to_regprocedure('private.app_workspace_has_feature(uuid,text)'),to_regprocedure('public.app_my_features()'),to_regprocedure('public.app_operator_feature_workspace(text)'),to_regprocedure('private.app_operator_feature_guard()')) and p.prosecdef and p.proconfig=array['search_path=""'] and not has_function_privilege('anon',p.oid,'execute') and coalesce(p.proacl::text,'')!~'(^|[{,])=')=4 then '예' else '아니오' end
union all select 'execute: check and list authenticated, finder service_role, guard nobody',case when has_function_privilege('authenticated','private.app_workspace_has_feature(uuid,text)','execute') and not has_function_privilege('service_role','private.app_workspace_has_feature(uuid,text)','execute') and has_function_privilege('authenticated','public.app_my_features()','execute') and not has_function_privilege('service_role','public.app_my_features()','execute') and has_function_privilege('service_role','public.app_operator_feature_workspace(text)','execute') and not has_function_privilege('authenticated','public.app_operator_feature_workspace(text)','execute') and not has_function_privilege('authenticated','private.app_operator_feature_guard()','execute') and not has_function_privilege('service_role','private.app_operator_feature_guard()','execute') and not has_function_privilege('anon','private.app_operator_feature_guard()','execute') then '예' else '아니오' end
union all select 'app_feed_items rows',(select count(*)::text from public.app_feed_items)
union all select 'app_feed_days rows',(select count(*)::text from public.app_feed_days)
union all select 'app_call_personal rows',(select count(*)::text from public.app_call_personal)
union all select 'app_call_edits rows',(select count(*)::text from public.app_call_edits)
union all select 'app_call_edit_history rows',(select count(*)::text from public.app_call_edit_history)
union all select 'app_tg_senders rows',(select count(*)::text from public.app_tg_senders)
union all select 'app_tg_day_senders rows',(select count(*)::text from public.app_tg_day_senders)
union all select 'app_feed_folders rows',(select count(*)::text from public.app_feed_folders)
union all select 'app_feed_rooms rows',(select count(*)::text from public.app_feed_rooms)
union all select 'app_feed_room_days rows',(select count(*)::text from public.app_feed_room_days)
union all select 'app_feed_summary_edits rows',(select count(*)::text from public.app_feed_summary_edits)
union all select 'app_feed_summary_edit_history rows',(select count(*)::text from public.app_feed_summary_edit_history)
union all select 'existing policies hash',md5(coalesce((select string_agg(c.relname||':'||p.polname::text||':'||p.polcmd::text||':'||p.polpermissive::text||':'||p.polroles::text||':'||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||':'||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by c.relname,p.polname) from pg_policy p join pg_class c on c.oid=p.polrelid where p.polrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_days'),to_regclass('public.app_call_personal'),to_regclass('public.app_call_edits'),to_regclass('public.app_call_edit_history'),to_regclass('public.app_tg_senders'),to_regclass('public.app_tg_day_senders'),to_regclass('public.app_feed_folders'),to_regclass('public.app_feed_rooms'),to_regclass('public.app_feed_room_days'),to_regclass('public.app_feed_summary_edits'),to_regclass('public.app_feed_summary_edit_history')) and p.polname<>'op_feature_read'),''))
union all select 'table grants and RLS hash',md5(coalesce((select string_agg(c.relname||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_days'),to_regclass('public.app_call_personal'),to_regclass('public.app_call_edits'),to_regclass('public.app_call_edit_history'),to_regclass('public.app_tg_senders'),to_regclass('public.app_tg_day_senders'),to_regclass('public.app_feed_folders'),to_regclass('public.app_feed_rooms'),to_regclass('public.app_feed_room_days'),to_regclass('public.app_feed_summary_edits'),to_regclass('public.app_feed_summary_edit_history'))),''))
union all select 'existing triggers hash',md5(coalesce((select string_agg(c.relname||':'||t.tgname::text||':'||t.tgenabled::text,',' order by c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid where t.tgrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_days'),to_regclass('public.app_call_personal'),to_regclass('public.app_call_edits'),to_regclass('public.app_call_edit_history'),to_regclass('public.app_tg_senders'),to_regclass('public.app_tg_day_senders'),to_regclass('public.app_feed_folders'),to_regclass('public.app_feed_rooms'),to_regclass('public.app_feed_room_days'),to_regclass('public.app_feed_summary_edits'),to_regclass('public.app_feed_summary_edit_history')) and not t.tgisinternal and t.tgname<>'trg_op_feature_guard'),''));
